import logging
from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple

from skydiscover.optimize.config import DatabaseConfig
from skydiscover.optimize.search.base_database import Program, ProgramDatabase

logger = logging.getLogger(__name__)


@dataclass
class EvolvedProgram(Program):
    """Program for the evolved database."""


def _score_of(program: EvolvedProgram) -> float:
    """Best available scalar score for a program (defaults to 0.0)."""
    metrics = getattr(program, "metrics", None) or {}
    for key in ("combined_score", "overall_score", "composite_score"):
        if key in metrics and metrics[key] is not None:
            return float(metrics[key])
    return 0.0


class EvolvedProgramDatabase(ProgramDatabase):
    """Tournament-based, diversity-rotating search strategy database.

    Informed by the measured window (stalled progress: 3 iterations without
    improvement; best parent over-reuse ratio 0.5; context anchor reuse 1.0):
    - Parents are drawn via tournament selection (size 3): stronger quality
      pressure than flat rank weighting to escape stagnation, while weaker
      programs still win occasionally (no degenerate softmax lock-in).
    - A HARD recency exclusion: the immediately previous parent can never be
      re-chosen on the next sample unless it is the only candidate. The soft
      50/50 re-draw of the previous policy left the reuse ratio at 0.5.
    - Context programs mix elite anchors with diversity fill biased toward
      under-sampled programs, and the most-reused context anchor is dropped
      half the time so the mutator sees fresh neighborhoods.
    - Multiobjective mode prefers the global Pareto front with tournaments.
    """

    def __init__(self, name: str, config: DatabaseConfig):
        super().__init__(name, config)
        self.initial_program = None
        self._last_parent_id: Optional[str] = None
        self._context_use: Dict[str, int] = {}

    def add(
        self, program: EvolvedProgram, iteration: Optional[int] = None, **kwargs
    ) -> str:
        """Add a program to the database."""
        if iteration == 0 or program.iteration_found == 0:
            self.initial_program = program

        self.programs[program.id] = program

        if iteration is not None:
            self.last_iteration = max(self.last_iteration, iteration)

        if self.config.db_path:
            self._save_program(program)

        self._update_best_program(program)

        logger.debug(f"Added program {program.id} to the evolve database")
        return program.id

    def _tournament_choice(self, candidates: List[EvolvedProgram]) -> EvolvedProgram:
        """Tournament selection: best of k=3 random draws (or fewer)."""
        if not candidates:
            raise ValueError("Empty candidate pool")
        k = min(3, len(candidates))
        pool = self.rng.sample(candidates, k)
        return max(pool, key=_score_of)

    def sample(
        self, num_context_programs: Optional[int] = 4, **kwargs
    ) -> Tuple[Dict[str, EvolvedProgram], Dict[str, List[EvolvedProgram]]]:
        """
        Picks a parent and set of context programs.

        Parent: tournament selection (Pareto front in multiobjective mode)
        with a hard exclusion of the previous parent.
        Context: elite anchors plus diversity fill toward under-sampled
        programs, excluding the parent; the most-reused anchor is dropped
        half the time.
        """
        candidates = list(self.programs.values())

        if len(candidates) == 0:
            raise ValueError("No candidates available for sampling")

        n_ctx = num_context_programs or 0

        if self.is_multiobjective_enabled():
            front = [p for p in self.get_pareto_front() if p.id in self.programs]
            parent_pool = front if front else candidates
        else:
            parent_pool = candidates

        # Hard recency exclusion: previous parent cannot be redrawn unless
        # it is the only available candidate.
        pool = [p for p in parent_pool if p.id != self._last_parent_id]
        if not pool:
            pool = list(parent_pool)
        parent = self._tournament_choice(pool)
        self._last_parent_id = parent.id

        # Context: elite anchors first, then diversity fill biased toward
        # under-sampled programs.
        others = [p for p in candidates if p.id != parent.id]
        examples: List[EvolvedProgram] = []
        if n_ctx > 0 and others:
            num_elite = max(1, n_ctx // 2)
            elites = sorted(others, key=_score_of, reverse=True)[:num_elite]
            # Drop the most-reused anchor half the time to rotate context.
            if len(elites) > 1 and self.rng.random() < 0.5:
                most_used = max(elites, key=lambda p: self._context_use.get(p.id, 0))
                if self._context_use.get(most_used.id, 0) > 0:
                    elites = [p for p in elites if p.id != most_used.id] or elites
            for elite in elites:
                if elite.id not in {e.id for e in examples}:
                    examples.append(elite)
            remaining = [p for p in others if p.id not in {e.id for e in examples}]
            # Bias fill toward least-used programs (under-explored neighbors).
            remaining.sort(key=lambda p: self._context_use.get(p.id, 0))
            for p in remaining:
                if len(examples) >= n_ctx:
                    break
                examples.append(p)
            for e in examples:
                self._context_use[e.id] = self._context_use.get(e.id, 0) + 1

        parent_dict = {"": parent}
        context_programs_dict = {"": examples}

        return parent_dict, context_programs_dict


# EVOLVE-BLOCK-END

